export function createKillStreak(container){
 const root=document.createElement('div');root.className='killstreak-pop';root.setAttribute('role','status');root.setAttribute('aria-live','polite');root.hidden=true;container.append(root);let timer,globalTimer;const banner=document.createElement('div');banner.className='killstreak-global';banner.setAttribute('role','status');banner.hidden=true;container.append(banner);
 return{announce(name,streak){clearTimeout(globalTimer);banner.textContent=`${name} is on a ${streak} kill streak!`;banner.hidden=false;globalTimer=setTimeout(()=>{banner.hidden=true;},3500);},show(streak){clearTimeout(timer);const number=document.createElement('b'),label=document.createElement('span');number.textContent=String(streak);label.textContent='KILL STREAK';root.replaceChildren(number,label);root.hidden=false;root.classList.remove('show');void root.offsetWidth;root.classList.add('show');timer=setTimeout(()=>{root.hidden=true;},2300);},clear(){clearTimeout(timer);clearTimeout(globalTimer);root.hidden=true;banner.hidden=true;}};
}
